function managerNameForBranch(branch){return String(branchSettings[branch]?.manager_name||DEFAULT_MANAGER_NAMES[branch]||"").trim().toUpperCase()}
function getManagerGreeting(displayName, assignments=[]){const branches=(assignments||[]).map(x=>x.branch);for(const preferred of ["CALL-CENTER","MOODZ MD"])if(branches.includes(preferred)&&managerNameForBranch(preferred))return managerNameForBranch(preferred);for(const branch of branches){const name=managerNameForBranch(branch);if(name)return name}return String(displayName||"").trim().toUpperCase()}
