window.signIn=async function signIn(){try{let email=$("email").value.trim(),password=$("password").value;if(email&&!email.includes("@"))email=email.toLowerCase().replace(/[^a-z0-9]+/g,".") .replace(/^\.+|\.+$/g,"")+"@m-daily.app";if(!email||!password)return toast("اكتب اسم المستخدم وكلمة المرور");const btn=document.querySelector("#login button.primary");if(btn){btn.disabled=true;btn.textContent="جارٍ تسجيل الدخول..."}const {data,error}=await db.auth.signInWithPassword({email,password});if(error)toast(error.message==="Invalid login credentials"?"بيانات الدخول غير صحيحة. راجع البريد وكلمة المرور، أو اطلب من المسؤول إعادة تعيين كلمة المرور.":"تعذر الدخول: "+error.message);else if(data.user){user=data.user;await load()}}catch(e){toast("خطأ أثناء الدخول: "+(e?.message||String(e)))}finally{const btn=document.querySelector("#login button.primary");if(btn){btn.disabled=false;btn.textContent="دخول"}}};
