async function refresh(){const {data,error}=await db.from("branch_records").select("*").order("created_at",{ascending:true});if(error)throw error;records=(data||[]).map(x=>({id:x.id,branch:x.branch,sheet:x.sheet,headers:x.headers||[],row:x.row_data||{},created_at:x.created_at}));await loadBranchSettings();await loadDashboardBranchSettings();await loadDailyRevenue();await loadOpeningHistory();await loadMonthlyTargets();await loadDailyTargets();await loadGoogleReviewTargets();await loadChecklist();await loadChecklistMonthHistory();fillFilters();render();applySavedTabOrder();renderAdminTools();renderTargetAdmin();renderChecklistAdmin();renderBranchTargets();renderBranchChecklist();renderProgressHero();renderManagerInputs();applyLanguage();renderChecklistMonthAdmin();renderAverageCheckAdmin();renderBranchComparison();renderMonthlyArchiveAdmin();formatEgyptHeader();makePanelsCollapsible();makePanelsCustomizable();applyRoleVisibility();convertEditButtonsToPencils();const manage=$("manageUsers");if(manage)manage.classList.toggle("hidden",!canManageUsers())}

function setupUserZoom(){
 const key="m-daily-user-zoom-v1";
 const controls=document.getElementById("zoomControls");
 if(!controls||controls.dataset.ready==="1")return;
 controls.dataset.ready="1";
 const valueEl=document.getElementById("zoomValue");
 let zoom=100;
 try{const saved=localStorage.getItem(key);if(saved)zoom=Math.max(70,Math.min(140,Number(saved)||100))}catch(e){}
 const apply=()=>{document.documentElement.style.setProperty("--md-user-zoom",String(zoom/100));if(valueEl)valueEl.textContent=zoom+"%";try{localStorage.setItem(key,String(zoom))}catch(e){}};
 document.getElementById("zoomIn")?.addEventListener("click",()=>{zoom=Math.min(140,zoom+10);apply()});
 document.getElementById("zoomOut")?.addEventListener("click",()=>{zoom=Math.max(70,zoom-10);apply()});
 document.getElementById("zoomReset")?.addEventListener("click",()=>{zoom=100;apply()});
 apply();
}

function egyptNow(){return new Date(new Date().toLocaleString("en-US",{timeZone:"Africa/Cairo"}))}
function egyptDate(value=new Date()){const d=new Date(value.toLocaleString("en-US",{timeZone:"Africa/Cairo"}));if(d.getHours()<7||(d.getHours()===7&&d.getMinutes()<50))d.setDate(d.getDate()-1);return new Intl.DateTimeFormat("en-CA",{timeZone:"Africa/Cairo",year:"numeric",month:"2-digit",day:"2-digit"}).format(d)}
function cairoCalendarDate(value=new Date()){return new Intl.DateTimeFormat("en-CA",{timeZone:"Africa/Cairo",year:"numeric",month:"2-digit",day:"2-digit"}).format(value)}
function managerDateBounds(){const today=cairoCalendarDate(),minDate=new Date(today+"T12:00:00Z");minDate.setUTCDate(minDate.getUTCDate()-2);return {today,min:minDate.toISOString().slice(0,10)}}
function isManagerDateAllowed(date){const {today,min}=managerDateBounds();return /^\d{4}-\d{2}-\d{2}$/.test(date)&&date>=min&&date<=today}
function formatEgyptHeader(){const el=$("headerDate");if(el){const n=egyptNow();el.textContent=new Intl.DateTimeFormat("ar-EG",{timeZone:"Africa/Cairo",weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(n)}}
async function loadBranchSettings(){const {data,error}=await db.from("branch_settings").select("*");if(error){console.error(error);return}branchSettings={};const today=egyptDate();for(const x of (data||[])){const savedDay=x.updated_at?egyptDate(new Date(x.updated_at)):"",manager_name=x.manager_name||"";if((x.opening_time||x.manager_arrival_time||x.closing_time)&&savedDay&&savedDay!==today){const {error:clearError}=await db.from("branch_settings").update({opening_time:null,manager_arrival_time:null,closing_time:null,updated_at:new Date().toISOString(),updated_by:user?.id||null}).eq("branch",x.branch);if(clearError)console.error(clearError);branchSettings[x.branch]={opening_time:"",manager_arrival_time:"",closing_time:"",manager_name};}else branchSettings[x.branch]={opening_time:x.opening_time?String(x.opening_time).slice(0,5):"",manager_arrival_time:x.manager_arrival_time?String(x.manager_arrival_time).slice(0,5):"",closing_time:x.closing_time?String(x.closing_time).slice(0,5):"",manager_name};}}

