 const legend=statuses.map((s,i)=>'<div class="md-legend-row"><i style="background:'+palette[i%palette.length]+'"></i><span>'+esc(s[0])+'</span><b>'+s[1]+'</b><small>'+(statusTotal?Math.round(s[1]/statusTotal*100):0)+'%</small></div>').join("");
